import re
import xml.etree.ElementTree as ET


def parse_order_info(xml_string):
    """
    解析UI XML数据，找到最后一个"更多"按钮对应的订单：店铺名 + 价格
    """
    root = ET.fromstring(xml_string)

    # 1. 找到所有 text="更多" 的节点（更多按钮）
    more_nodes = []
    for node in root.iter('node'):
        if node.get('text') == '更多':
            more_nodes.append(node)

    if not more_nodes:
        return None, None

    # 2. 取最后一个更多按钮
    last_more_node = more_nodes[-1]

    # 3. 向上找父节点，定位到整个订单卡片区域
    current = last_more_node
    order_card = None
    # 向上找4层父节点（匹配UI层级结构）
    for _ in range(4):
        current = current.findall('..')[0] if current.findall('..') else None
        if not current:
            break
    order_card = current

    if not order_card:
        return None, None

    # 4. 在订单卡片内查找 店铺名 和 价格
    shop_name = None
    order_price = None

    # 遍历订单卡片下所有节点
    for node in order_card.iter('node'):
        text = node.get('text', '').strip()
        content_desc = node.get('content-desc', '').strip()

        # 提取店铺名（content-desc带店铺/文本是店铺名）
        if (content_desc and ("店" in content_desc or "官方" in content_desc)) or \
                (text and ("店" in text or "官方" in text)):
            if text:
                shop_name = text
            elif content_desc:
                shop_name = content_desc

        # 提取价格（以¥开头的文本）
        if text.startswith('¥'):
            order_price = text

    return shop_name, order_price


import xml.etree.ElementTree as ET


def parse_invoice_xml(xml_str, shifu_kuan, servi):
    """
    从UI XML中提取：订单编号、开票金额
    专门适配：¥ 后跟着 18 和 .80 这种拆分格式
    """
    root = ET.fromstring(xml_str)

    order_id = None
    invoice_amount = None

    # 遍历所有节点
    all_nodes = list(root.iter())

    # ========== 1. 提取 订单编号 ==========
    for i, node in enumerate(all_nodes):
        if node.attrib.get("text", "") == "订单编号":
            if i + 1 < len(all_nodes):
                order_id = all_nodes[i + 1].attrib.get("text", "").strip()
            break

    # ========== 2. 提取 开票金额（终极修复版）==========
    for i, node in enumerate(all_nodes):
        if node.attrib.get("text", "") == "开票金额":
            amount_parts = []
            j = i + 1

            # 连续提取后面的文本：不管是数字、小数点、¥ 都直接收
            while j < len(all_nodes):
                current_text = all_nodes[j].attrib.get("text", "").strip()

                # 空文本就停止
                if not current_text:
                    break

                # 只要是金额相关字符，全部收集
                if current_text in ("¥", ".") or current_text.replace(".", "").isdigit():
                    amount_parts.append(current_text)
                else:
                    break  # 不是金额就停止

                j += 1

            # 拼接完整
            full_text = "".join(amount_parts)
            # 去掉 ¥
            if "¥" in full_text:
                full_text = full_text.replace("¥", "")
            invoice_amount = full_text.strip()
            break

    return {
        "订单编号": order_id,
        "实付": invoice_amount
    }
