from lxml import etree

def find_id_from_area_2(str_xml, x1_1, x2_2, y1_1, y2_2):
  #xml = d.dump_hierarchy()
  tree = etree.fromstring(str_xml.encode('utf-8'))

  # 目标坐标范围：判断控件是否包含该坐标
  # target_point = (x1, y1)  # 你需要检查的点

  # 存储符合条件的控件信息 (面积, 控件, 中心坐标)
  candidates = []
  zuobiaodian = []
  elements = tree.xpath('//node')
  for elem in elements:
    bounds_str = elem.get('bounds', '')
    resource_id = elem.get('resource-id', '')
    text = elem.get('text', '')
    contentdesc = elem.get('content-desc', '')
    if not bounds_str:
      continue

    # 解析bounds坐标 [x1,y1][x2,y2]
    coords = re.findall(r'\[(\d+),(\d+)]\[(\d+),(\d+)]', bounds_str)
    if not coords:
      continue

    x1, y1, x2, y2 = map(int, coords[0])
    # print(x1, y1, x2, y2)

    if (
            x1_1 < x1 and x2 < x2_2 and y1_1 < y1 and y2 < y2_2 and y2 - y1 == x2 - x1 and x1 != 0 and y1 != 0 and resource_id == "" and text == "" and contentdesc == ""):
      # print("------------------------------------------------------")
      # print(x1, y1, x2, y2)
      # print(resource_id,text,contentdesc)
      center_x = (x1 + x2) // 2
      center_y = (y1 + y2) // 2
      # print(center_x,center_y)

      zuobiaodian.append((center_x, center_y))
  zuobiaodian = list(set(zuobiaodian))
  # print("zuobiaodian=",zuobiaodian)
  zuobiaodian1 = zuobiaodian
  for elem in elements:

    bounds_str = elem.get('bounds', '')

    if not bounds_str:
      continue

    # 解析bounds坐标 [x1,y1][x2,y2]
    coords = re.findall(r'\[(\d+),(\d+)]\[(\d+),(\d+)]', bounds_str)
    if not coords:
      continue

    x1, y1, x2, y2 = map(int, coords[0])
    # print("x1, y1, x2, y2",x1, y1, x2, y2)
    for iii in zuobiaodian:
      if (x1 != 0 and y1 != 0 and x1 < iii[0] < x2 and y1 < iii[1] < y2):
        print("x1, y1, x2, y2", x1, y1, x2, y2)
        resource_id = elem.get('resource-id', '')
        text = elem.get('text', '')
        contentdesc = elem.get('content-desc', '')
        # print(resource_id, text, contentdesc)
